import{_ as s,o as e,c as a,a4 as t}from"./chunks/framework.DA9C4Pbl.js";const k=JSON.parse('{"title":"Install & Login","description":"","frontmatter":{"title":"Install & Login","visibility":"public","audience":"developer","tier":"reference","source":"handwritten"},"headers":[],"relativePath":"reference/cli-login.md","filePath":"reference/cli-login.md"}'),n={name:"reference/cli-login.md"};function l(h,i,o,r,d,p){return e(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="install-login" tabindex="-1">Install &amp; Login <a class="header-anchor" href="#install-login" aria-label="Permalink to “Install &amp; Login”">​</a></h1><p>Simply issue the following in a Terminal:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Windows users</p><p>Installing on Windows has a few extra steps (Python on <code>PATH</code>, the <code>Scripts</code> directory on <code>PATH</code>, app-execution aliases). See the dedicated <a href="/start/windows-python">Installing on Windows</a> page if <code>pip</code> or <code>arcsecond</code> are &quot;not recognized&quot; in PowerShell.</p></div><p>To upgrade an existing Arcsecond installation:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span></code></pre></div><p>The help is available like any other command-line tool:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>For subcommands:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">comman</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>The Arcsecond CLI works like a tool such as <code>git</code>: <code>arcsecond</code> is the main entry point, followed by a command. Many commands directly map to Arcsecond resources.</p><h2 id="which-server" tabindex="-1">Which server <a class="header-anchor" href="#which-server" aria-label="Permalink to “Which server”">​</a></h2><p>The CLI points at one API server at a time, and every command talks to that one. By default it is the cloud, <code>api.arcsecond.io</code>. To work against your own Arcsecond.local instead:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> use</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> local</span></span></code></pre></div><p><code>arcsecond setup</code> registers <code>local</code> for you (<code>http://localhost:8800</code>); from another computer, register the machine&#39;s address first — <code>arcsecond api add local http://192.168.1.42:8800</code> — see <a href="/start/network">Access from Other Computers</a>. <code>arcsecond api</code> lists the servers, the current one marked with <code>*</code>, and <code>arcsecond api use cloud</code> points back. Credentials are kept per server, so log in once on each.</p><p>For a script or a scheduled job, <code>ARCSECOND_API=local</code> in the environment selects a server for that process alone, without moving the pointer.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h2><p>To use the CLI, you need an account on the server the CLI points at. In your settings page — on <a href="https://www.arcsecond.io" target="_blank" rel="noreferrer">arcsecond.io</a>, or on your own Arcsecond.local — you will find two kinds of credentials:</p><ul><li>an Access Key for broad access to your resources</li><li>an Upload Key for upload-only workflows</li></ul><p>Use an Access Key only on trusted computers. If you only need to upload files, prefer an Upload Key.</p><h3 id="interactive-login" tabindex="-1">Interactive login <a class="header-anchor" href="#interactive-login" aria-label="Permalink to “Interactive login”">​</a></h3><p>Run:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>The CLI will prompt for:</p><ul><li><code>username</code></li><li><code>type</code> (<code>access</code> or <code>upload</code>)</li><li><code>key</code></li></ul><p>Your credential is stored locally in <code>~/.config/arcsecond/config.ini</code>.</p><h3 id="non-interactive-login" tabindex="-1">Non-interactive login <a class="header-anchor" href="#non-interactive-login" aria-label="Permalink to “Non-interactive login”">​</a></h3><p>To skip prompts, pass all values explicitly:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">usernam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> access</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">access-ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>or:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --username</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">usernam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">upload-ke</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">y</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Logging in again overwrites the stored credential if the login succeeds.</p><p>If you think a key is compromised, regenerate it from your profile settings on <a href="https://www.arcsecond.io" target="_blank" rel="noreferrer">arcsecond.io</a>. The CLI cannot regenerate keys for you.</p>',33)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
